bot.command('craw', async (ctx) => {
    try {
        // Cek apakah ini reply message
        const isReply = ctx.message.reply_to_message;
        const input = ctx.message.text.replace('/craw', '').trim();

        let content, filename;

        if (isReply) {
            // Mode 1: Reply message + filename
            if (!input) {
                return ctx.reply(
                    'Masukin : /craw Nama File\nExample : /craw File.py'
                );
            }
            content = ctx.message.reply_to_message.text  ctx.message.reply_to_message.caption  '';
            filename = input;
        } else {
            // Mode 2: Traditional Code|Nama File
            if (!input) {
                return ctx.reply(
                    'Masukin : Code|Nama File\nExample : Hello World|File.py'
                );
            }

            const parts = input.split('|');

            if (parts.length !== 2) {
                return ctx.reply(
                    'Masukin : Code|Nama File\nExample : Hello World|File.py'
                );
            }

            [content, filename] = parts.map(part => part.trim());
        }

        if (!content || !filename) {
            return ctx.reply(
                'Text atau nama file tidak boleh kosong!\n' +
                'Contoh: Hello World|Test.py'
            );
        }

        const validFilename = filename.replace(/[^a-zA-Z0-9._-]/g, '_');

        const processingMsg = await ctx.reply('Mengupload ke Vortex Code...', { 
            parse_mode: 'Markdown' 
        });

        const response = await fetch("https://code.vortexx.web.id/api/submit", {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                filename: validFilename,
                content: content
            })
        });

        const result = await response.json();

        if (result.success) {
            const responseMessage = 
                Berhasil diupload!\n\n +
                • **File:** \${validFilename}\\n +
                • **ID:** \${result.id}\``;

            await ctx.telegram.editMessageText(
                ctx.chat.id,
                processingMsg.message_id,
                null,
                responseMessage,
                { 
                    parse_mode: 'Markdown',
                    disable_web_page_preview: true
                }
            );

            await ctx.reply(
                'Click Button Dibawah Untuk Melihat Preview Raw And Preview Website',
                {
                    parse_mode: 'Markdown',
                    reply_markup: {
                        inline_keyboard: [
                            [
                                { text: 'ᴏᴘᴇɴ ʙʀᴏᴡsᴇʀ', url: https://code.vortexx.web.id/view/${result.id} },
                                { text: 'ɢᴇᴛ ʀᴀᴡ', url: https://code.vortexx.web.id/api/get/${result.id} }
                            ]
                        ]
                    }
                }
            );

        } else {
            throw new Error(result.error || 'Upload gagal');
        }

    } catch (error) {
        console.error('Bot Error:', error);

        let errorMessage = Error!\n${error.message};

        if (error.message.includes('Failed to fetch')) {
            errorMessage = 'Vortex Code API tidak bisa diakses!\nPeriksa koneksi internet atau coba lagi nanti.';
        } else if (error.message.includes('GitHub API')) {
            errorMessage = 'GitHub API Error!\nDatabase mungkin sedang maintenance.';
        }

        ctx.reply(errorMessage, { parse_mode: 'Markdown' });
    }
});

