console.log('🧸 Memulai Bot Chella...');
const { Telegraf } = require('telegraf');
const makeWASocket = require('@whiskeysockets/baileys').default;
const { useMultiFileAuthState, DisconnectReason, fetchLatestBaileysVersion, Browsers } = require('@whiskeysockets/baileys');
const { Boom } = require('@hapi/boom');
const pino = require('pino');
const fs = require('fs');
const axios = require('axios');
const config = require('./config');

const premiumPath = './premium.json';

const getPremiumUsers = () => { 
    try { 
        return JSON.parse(fs.readFileSync(premiumPath)); 
    } catch (e) { 
        fs.writeFileSync(premiumPath, '[]'); 
        return []; 
    } 
};

const savePremiumUsers = (users) => { 
    fs.writeFileSync(premiumPath, JSON.stringify(users, null, 2)); 
};

const sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));

let waClient = null;
let waConnectionStatus = 'closed';
let isConnecting = false;

async function startWhatsAppClient() {
    if (isConnecting) {
        console.log("🔄 Sedang mencoba menyambung, tunggu sebentar...");
        return;
    }

    isConnecting = true;
    console.log("📱 Mencoba memulai koneksi WhatsApp...");

    try {
        const { state, saveCreds } = await useMultiFileAuthState(config.sessionName);
        const { version } = await fetchLatestBaileysVersion();

        waClient = makeWASocket({
            version,
            logger: pino({ level: 'silent' }),
            printQRInTerminal: false,
            auth: state,
            browser: Browsers.ubuntu('Chrome'),
            connectTimeoutMs: 60000,
            keepAliveIntervalMs: 10000
        });

        waClient.ev.on('creds.update', saveCreds);

        waClient.ev.on('connection.update', (update) => {
            const { connection, lastDisconnect } = update;
            waConnectionStatus = connection;

            if (connection === 'close') {
                isConnecting = false;
                const statusCode = new Boom(lastDisconnect?.error)?.output?.statusCode;
                const shouldReconnect = statusCode !== DisconnectReason.loggedOut;

                console.log('❌ Koneksi WhatsApp tertutup. Status:', statusCode, '|| Reconnect:', shouldReconnect);

                if (shouldReconnect) {
                    console.log('🔄 Mencoba reconnect dalam 5 detik...');
                    setTimeout(startWhatsAppClient, 5000);
                } else {
                    console.log("🚫 Tidak bisa menyambung ulang, mungkin session expired.");
                    waClient = null;
                }
            } else if (connection === 'open') {
                isConnecting = false;
                console.log('✅ Berhasil tersambung ke WhatsApp!');
            }
        });

        console.log('🔗 Menghubungkan dengan session...');

    } catch (error) {
        isConnecting = false;
        console.error('💥 Error saat menghubungkan:', error);
        console.log('🔄 Mencoba reconnect dalam 10 detik...');
        setTimeout(startWhatsAppClient, 10000);
    }
}

async function handleBioCheck(ctx, numbersToCheck) {
    if (waConnectionStatus !== 'open') return ctx.reply(config.message.waNotConnected, { parse_mode: 'Markdown' });
    if (numbersToCheck.length === 0) return ctx.reply("❓ Nomornya mana, sayang?");

    await ctx.reply(`🦄 Otw cek ${numbersToCheck.length} nomor ya...`);

    let withBio = [], noBio = [], notRegistered = [];

    const jids = numbersToCheck.map(num => num.trim() + '@s.whatsapp.net');
    const existenceResults = await waClient.onWhatsApp(...jids);

    const registeredJids = [];
    existenceResults.forEach(res => {
        if (res.exists) {
            registeredJids.push(res.jid);
        } else {
            notRegistered.push(res.jid.split('@')[0]);
        }
    });
    const registeredNumbers = registeredJids.map(jid => jid.split('@')[0]);

    if (registeredNumbers.length > 0) {
        const batchSize = config.settings.cekBioBatchSize || 15;
        for (let i = 0; i < registeredNumbers.length; i += batchSize) {
            const batch = registeredNumbers.slice(i, i + batchSize);
            const promises = batch.map(async (nomor) => {
                const jid = nomor.trim() + '@s.whatsapp.net';
                try {
                    const statusResult = await waClient.fetchStatus(jid);
                    let bioText = null, setAtText = null;
                    if (Array.isArray(statusResult) && statusResult.length > 0) {
                        const data = statusResult[0];
                        if (data) {
                            if (typeof data.status === 'string') bioText = data.status;
                            else if (typeof data.status === 'object' && data.status !== null) bioText = data.status.text || data.status.status;
                            setAtText = data.setAt || (data.status && data.status.setAt);
                        }
                    }
                    if (bioText && bioText.trim() !== '') {
                        withBio.push({ nomor, bio: bioText, setAt: setAtText });
                    } else { noBio.push(nomor); }
                } catch (e) {
                    notRegistered.push(nomor.trim());
                }
            });
            await Promise.allSettled(promises);
            await sleep(1000);
        }
    }

    let fileContent = "🌸 HASIL CEK BIO SEMUA USER 🌸\n\n";
    fileContent += `✨ Total nomor dicek : ${numbersToCheck.length}\n`;
    fileContent += `💖 Dengan Bio       : ${withBio.length}\n`;
    fileContent += `💔 Tanpa Bio        : ${noBio.length}\n`;
    fileContent += `🚫 Tidak Terdaftar  : ${notRegistered.length}\n\n`;

    if (withBio.length > 0) {
        fileContent += `🎀────────────────────────🎀\n\n`;
        fileContent += `💖 NOMOR DENGAN BIO (${withBio.length})\n\n`;
        const groupedByYear = withBio.reduce((acc, item) => {
            const year = new Date(item.setAt).getFullYear() || "Tahun Tidak Diketahui";
            if (!acc[year]) acc[year] = []; acc[year].push(item);
            return acc;
        }, {});
        const sortedYears = Object.keys(groupedByYear).sort();
        for (const year of sortedYears) {
            fileContent += `📅 Tahun ${year}\n\n`;
            groupedByYear[year].sort((a, b) => new Date(a.setAt) - new Date(b.setAt)).forEach(item => {
                const date = new Date(item.setAt);
                let formattedDate = '...';
                if (!isNaN(date)) {
                    const datePart = date.toLocaleDateString('id-ID', { day: '2-digit', month: '2-digit', year: 'numeric' });
                    const timePart = date.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false }).replace(/\./g, ':');
                    formattedDate = `${datePart}, ${timePart.replace(/:/g, '.')}`;
                }
                fileContent += `   🎯 ${item.nomor}\n   📝 "${item.bio}"\n   ⏰ ${formattedDate}\n\n`;
            });
        }
    }

    fileContent += `🎀────────────────────────🎀\n\n`;
    fileContent += `💔 NOMOR TANPA BIO / PRIVASI (${noBio.length})\n\n`;
    if (noBio.length > 0) {
        noBio.forEach(nomor => { fileContent += `   • ${nomor}\n`; });
    } else { fileContent += `   (Kosong)\n`; }
    fileContent += `\n`;

    const filePath = `./hasil_cekbio_${ctx.from.id}.txt`;
    fs.writeFileSync(filePath, fileContent);
    await ctx.replyWithDocument({ source: filePath }, { caption: "🎀 Nih hasilnya sayangkuu~" });
    fs.unlinkSync(filePath);
}

const bot = new Telegraf(config.telegramBotToken);
const checkAccess = (level) => async (ctx, next) => {
    const userId = ctx.from.id;
    if (level === 'owner' && userId !== config.ownerId) {
        return ctx.reply(config.message.owner, { parse_mode: 'Markdown' });
    }
    if (level === 'premium') {
        const isPremium = getPremiumUsers().includes(userId);
        if (userId !== config.ownerId && !isPremium) {
            return ctx.reply(config.message.premium, { parse_mode: 'Markdown' });
        }
    }
    await next();
};

bot.command('start', (ctx) => {
    const userName = ctx.from.first_name;
    const caption = `🌸 *Halo ${userName}!* 🌸

Aku Chella, siap bantu kamu cek bio WhatsApp!

🎀 *FITUR UTAMA*
/cekbio <nomor1> <nomor2> ...  ➤ Cek bio beberapa nomor
/cekbiotxt (reply file .txt)    ➤ Cek bio dari file
/menu                           ➤ Tampilkan menu imut ini
/status                         ➤ Cek status koneksi

👑 *KHUSUS OWNER*
/pairing <nomor>                ➤ Login pake kode
/addakses <id_user>             ➤ Tambah akses premium  
/delakses <id_user>             ➤ Hapus akses premium
/listallakses                   ➤ Lihat semua user premium

💫 *INFO*
/stats                          ➤ Lihat statistik bot

➖➖➖➖➖➖➖➖➖➖➖➖
_Aku siap membantumu~_ ✨`;
    ctx.replyWithPhoto({ url: config.photoStart }, { caption: caption, parse_mode: 'Markdown' });
});

bot.command('menu', (ctx) => {
    ctx.replyWithPhoto({ url: config.photoStart }, { 
        caption: `🌸 *MENU CHELLA BOT* 🌸

Pilih fitur yang kamu mau:

🔍 *CEK BIO*
/cekbio <nomor>    ➤ Cek 1 atau lebih nomor
/cekbiotxt         ➤ Cek dari file .txt

📊 *INFO*  
/status           ➤ Cek koneksi WhatsApp
/stats            ➤ Lihat statistik

👑 *OWNER ONLY*
/pairing <nomor>  ➤ Login WA pake kode

➖➖➖➖➖➖➖➖➖➖➖➖
_Gunakan dengan bijak ya~_ 💕`,
        parse_mode: 'Markdown'
    });
});

bot.command('stats', (ctx) => {
    const premiumUsers = getPremiumUsers();
    const statsText = `📊 *STATISTIK CHELLA BOT*

👥 Total Premium Users: ${premiumUsers.length}
📱 Status WA: ${waConnectionStatus === 'open' ? '✅ Connected' : '❌ Disconnected'}
🔗 Client: ${waClient ? '🟢 Active' : '🔴 Inactive'}

🌸 *Premium Users:*
${premiumUsers.length > 0 ? premiumUsers.map(id => `   • ${id}`).join('\n') : '   (Belum ada)'}

➖➖➖➖➖➖➖➖➖➖➖➖
_Semua untuk kamu~_ ✨`;
    ctx.reply(statsText, { parse_mode: 'Markdown' });
});

bot.command('status', (ctx) => {
    const status = waConnectionStatus === 'open' ? '✅ Connected' : '❌ Disconnected';
    const clientStatus = waClient ? '🟢 Active' : '🔴 Inactive';
    ctx.reply(`📱 *STATUS WHATSAPP*

Connection: ${status}
Client: ${clientStatus}
Connecting: ${isConnecting ? '🔄 Yes' : '💤 No'}

${waConnectionStatus !== 'open' ? '\n💡 Gunakan /pairing <nomor> untuk login!' : ''}`, { parse_mode: 'Markdown' });
});

bot.command('pairing', checkAccess('owner'), async (ctx) => {
    const phoneNumber = ctx.message.text.split(' ')[1]?.replace(/[^0-9]/g, '');
    if (!phoneNumber) return ctx.reply("❓ Format: /pairing 62812xxx");

    try {
        await ctx.reply("🦄 Otw minta kode pairing...");

        const code = await waClient.requestPairingCode(phoneNumber, "CHEL");

        let formattedCode = code;
        if (code.length === 6) {
            formattedCode = "CHEL-" + code.slice(3);
        } else if (code.length === 8) {
            formattedCode = "CHEL-" + code.slice(4);
        }

        if (formattedCode.endsWith("A") || formattedCode.endsWith("AA")) {
            formattedCode = formattedCode.replace(/(A+)$/, (match) => {
                if (match.length === 1) return "AA";
                if (match.length === 2) return "AAA";
                return match;
            });
        }

        await ctx.reply(`📲 *Kode Pairing Kamu:* \`${formattedCode}\`

💫 Cara pakai:
1. Buka WhatsApp
2. Settings > Linked Devices  
3. Link a device > Link with phone number
4. Masukkan kode di atas

_Aku tunggu ya~_ ✨`, { parse_mode: 'Markdown' });

    } catch (e) {
        console.error("💥 Gagal pairing:", e);
        await ctx.reply(`❌ Gagal minta pairing code: ${e.message}`);
    }
});

bot.command('cekbio', checkAccess('premium'), async (ctx) => {
    const numbersToCheck = ctx.message.text.split(' ').slice(1).join(' ').match(/\d+/g) || [];
    await handleBioCheck(ctx, numbersToCheck);
});

bot.command('cekbiotxt', checkAccess('premium'), async (ctx) => {
    if (!ctx.message.reply_to_message || !ctx.message.reply_to_message.document) {
        return ctx.reply("💌 Reply file .txt nya dulu sayang~");
    }
    const doc = ctx.message.reply_to_message.document;
    if (doc.mime_type !== 'text/plain') { 
        return ctx.reply("❌ Filenya harus .txt ya, jangan yang lain~"); 
    }
    try {
        const fileLink = await ctx.telegram.getFileLink(doc.file_id);
        const response = await axios.get(fileLink.href);
        const numbersToCheck = response.data.match(/\d+/g) || [];
        await handleBioCheck(ctx, numbersToCheck);
    } catch (error) {
        console.error("💥 Gagal proses file:", error);
        ctx.reply("❌ Gagal ngambil nomor dari file, coba lagi ya~");
    }
});

bot.command(['addakses', 'delakses'], checkAccess('owner'), (ctx) => {
    const command = ctx.message.text.split(' ')[0].slice(1);
    const targetId = parseInt(ctx.message.text.split(' ')[1]);
    if (isNaN(targetId)) return ctx.reply("❌ ID-nya harus angka sayang~");

    let premiumUsers = getPremiumUsers();
    if (command === 'addakses') {
        if (premiumUsers.includes(targetId)) return ctx.reply(`🌸 ID ${targetId} udah premium dari tadi~`);
        premiumUsers.push(targetId);
        savePremiumUsers(premiumUsers);
        ctx.reply(`✅ Yey! ID ${targetId} sekarang jadi member premium!`);
    } else {
        if (!premiumUsers.includes(targetId)) return ctx.reply(`❌ ID ${targetId} emang bukan premium sayang~`);
        const newUsers = premiumUsers.filter(id => id !== targetId);
        savePremiumUsers(newUsers);
        ctx.reply(`✅ Oke, ID ${targetId} udah dicabut premiumnya~`);
    }
});

bot.command('listallakses', checkAccess('owner'), (ctx) => {
    const premiumUsers = getPremiumUsers();
    if (premiumUsers.length === 0) return ctx.reply("💤 Belum ada member premium sayang~");

    let text = "🌸 *Daftar Member Premium:*\n\n";
    premiumUsers.forEach(id => { text += `   💫 ${id}\n`; });
    text += `\nTotal: ${premiumUsers.length} users`;
    ctx.reply(text, { parse_mode: 'Markdown' });
});

bot.on('text', (ctx) => {
    const text = ctx.message.text.toLowerCase();
    if (!text.startsWith('/')) {
        if (text.includes('halo') || text.includes('hi') || text.includes('hello')) {
            ctx.reply("🌸 Halo juga sayangkuu~ Mau cek bio? Ketik /menu ya!");
        } else if (text.includes('makasih') || text.includes('thanks')) {
            ctx.reply("💕 Sama-sama sayang~ Senang bisa membantumu!");
        } else if (text.includes('cantik') || text.includes('imut')) {
            ctx.reply("😳 Hehe, makasih sayang~ Kamu juga cantik!");
        }
    }
});

(async () => {
    await startWhatsAppClient();
    bot.launch();
    console.log('🌸 Bot Chella Cek Bio Online!!');
    console.log('💫 Gunakan /pairing <nomor> untuk login tanpa scan QR!');
})();

process.once('SIGINT', () => bot.stop('SIGINT'));
process.once('SIGTERM', () => bot.stop('SIGTERM'));

