// t.me/JooModdss

const axios = require("axios");
const konstol = "https://api.mail.tm";

function randomStr(len = 10) {
  return Math.random().toString(36).substring(2, 2 + len);
}

async function createTempEmail() {
  const domainRes = await axios.get(konstol + "/domains");
  const domain = domainRes.data["hydra:member"][0].domain;

  const address = `${randomStr(8)}@${domain}`;
  const password = randomStr(12);

  await axios.post(konstol + "/accounts", {
    address,
    password
  });

  const tokenRes = await axios.post(konstol + "/token", {
    address,
    password
  });

  return {
    email: address,
    password,
    token: tokenRes.data.token
  };
}

async function getMessages(token) {
  const res = await axios.get(konstol + "/messages", {
    headers: {
      Authorization: `Bearer ${token}`
    }
  });
  return res.data["hydra:member"];
}

async function getMessageDetail(id, token) {
  const res = await axios.get(konstol + "/messages/" + id, {
    headers: {
      Authorization: `Bearer ${token}`
    }
  });
  return res.data;
}

async function deleteMessage(id, token) {
  await axios.delete(konstol + "/messages/" + id, {
    headers: {
      Authorization: `Bearer ${token}`
    }
  });
  return true;
}

module.exports = {
  createTempEmail,
  getMessages,
  getMessageDetail,
  deleteMessage
};

