async function cloudkuUpload(buffer) {
  const { ext, mime } = (await FileType.fileTypeFromBuffer(buffer)) || {
    ext: "bin",
    mime: "application/octet-stream",
  };

  const form = new FormData();
  form.append("file", buffer, {
    filename: `file.${ext}`,
    contentType: mime,
  });

  const res = await fetch("https://cloudkuimages.guru/upload.php", {
    method: "POST",
    body: form,
    headers: form.getHeaders(),
  });

  const json = await res.json().catch(() => null);
  if (!json || json.status !== "success") throw "Cloudku fail";

  return json.result.url;
}

async function catboxUpload(buffer) {
  const { ext } = (await FileType.fileTypeFromBuffer(buffer)) || { ext: "bin" };

  const form = new FormData();
  form.append("reqtype", "fileupload");
  form.append("fileToUpload", buffer, {
    filename: `file.${ext}`,
  });

  const res = await fetch("https://catbox.moe/user/api.php", {
    method: "POST",
    body: form,
    headers: form.getHeaders(),
  });

  const text = await res.text();
  if (!text.startsWith("https://")) throw "Catbox fail";

  return text;
}

async function pixhostUpload(buffer) {
  const service = new ImageUploadService("pixhost.to");
  const { directLink } = await service.uploadFromBinary(buffer, "image.png");
  return directLink.toString();
}

module.exports = composer.middleware();

module.exports.enable = () => (enabled = true);
module.exports.disable = () => (enabled = false);

