#!/bin/bash

echo "Starting JooModdss Ultimate Security & Theme Installation..."
echo "=============================================================="

PANEL_PATH="/var/www/pterodactyl"
BACKUP_DIR="/root/pterodactyl_backups"
TIMESTAMP=$(date -u +"%Y-%m-%d-%H-%M-%S")

RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
PURPLE='\033[0;35m'
CYAN='\033[0;36m'
NC='\033[0m'

mkdir -p "$BACKUP_DIR"

print_status() {
    echo -e "${BLUE}${NC}$1"
}

print_success() {
    echo -e "${GREEN}${NC}$1"
}

print_warning() {
    echo -e "${YELLOW}${NC}$1"
}

print_error() {
    echo -e "${RED}${NC}$1"
}

backup_file() {
    local file_path="$1"
    local backup_name="$2"

    if [ -f "$file_path" ]; then
        cp "$file_path" "$BACKUP_DIR/${backup_name}_${TIMESTAMP}.bak"
        print_status "Backed up: $backup_name"
        return 0
    fi
    return 1
}

create_protected_file() {
    local file_path="$1"
    local content="$2"
    local backup_name="$3"

    backup_file "$file_path" "$backup_name"
    mkdir -p "$(dirname "$file_path")"
    echo "$content" > "$file_path"
    chmod 644 "$file_path"
    print_success "Protected: $(basename "$file_path")"
}

print_status "Installing Security Protections..."

