        $user = Auth::user();
        if (!$user || $user->id !== 1) {
            abort(403, "✖ JooModdss Protection :: Location view denied");
        }

        return $this->view->make("admin.locations.view", [
            "location" => $this->repository->getWithNodes($id),
        ]);
    }

