const supportEmails = [
  'support@support.whatsapp.com',
  'smb@support.whatsapp.com',
  'smb@whatsapp.com',
  'android@support.whatsapp.com',
  'iphone@support.whatsapp.com',
  'smb_web@support.whatsapp.com',
  'business-support@whatsapp.com'
];

function doGet(e) {
  const nomor = e.parameter.nomor;

  if (!nomor) {
    return json({
      status: false,
      message: 'Parameter nomor wajib diisi. Contoh: ?nomor=+6283162605767'
    });
  }

  const body = `Halo tim Whatsapp

Saya ingin menyampaikan keluhan saya. Beberapa hari ini saya mencoba masuk ke akun WhatsApp menggunakan nomor saya, tetapi selalu gagal. Di layar muncul tulisan merah kalau nomor saya tidak bisa diverifikasi. Akibatnya saya sama sekali tidak bisa login.

Padahal nomor saya aktif, masih bisa menerima SMS dan panggilan. Saya juga sudah coba semua cara: ganti jaringan, hapus data aplikasi, install ulang WhatsApp, bahkan menunggu beberapa jam sebelum mencoba lagi. Tapi hasilnya tetap sama, verifikasi tidak bisa dilakukan.

Saya merasa bingung, karena nomor ini resmi dan masih aktif dipakai untuk komunikasi sehari-hari. Saya sangat membutuhkan WhatsApp untuk urusan keluarga dan pekerjaan, jadi tolong sekali tim WhatsApp membantu memperbaiki masalah ini agar saya bisa kembali menggunakan akun saya.

Terima kasih banyak atas bantuan dan perhatian dari tim.

Hormat saya
[${nomor}]`;

  supportEmails.forEach(email => {
    MailApp.sendEmail({
      to: email,
      subject: '',
      body: body
    });
  });

  return json({
    status: true,
    message: 'Email berhasil dikirim',
    nomor: nomor,
    total_email: supportEmails.length
  });
}

function json(data) {
  return ContentService
    .createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}
